# The largest inscribed circle: center c, radius R. Boundary point must be inside union.
# Equivalent: R = max over c of min over boundary-directions... 
# Do: for center c, R(c) = the largest R s.t. all points at distance R are inside union.
# The union is star-shaped-ish from center. Compute R(c) by ray casting.
def R_of(cx,cy,n=360):
    R=1e9
    for t in np.linspace(0,2*np.pi,n,endpoint=False):
        dx,dy=np.cos(t),np.sin(t)
        # find max s where (cx+s*dx,cy+s*dy) still inside union, scanning outward
        lo,hi=0.0,2.0
        # ensure hi outside
        if union_inside(cx+hi*dx,cy+hi*dy): 
            continue
        for _ in range(40):
            mid=(lo+hi)/2
            if union_inside(cx+mid*dx,cy+mid*dy): lo=mid
            else: hi=mid
        R=min(R,lo)
    return R
