def inside(px,py,poly):
    n=len(poly)
    for i in range(n):
        x1,y1=poly[i]; x2,y2=poly[(i+1)%n]
        if (x2-x1)*(py-y1)-(y2-y1)*(px-x1) < -1e-9:
            return False
    return True
def max_circle(polys, center_range=0.6, ngrid=41, nang=180):
    best=0;bc=(0,0)
    for cx in np.linspace(-center_range,center_range,ngrid):
        for cy in np.linspace(-center_range,center_range,ngrid):
